assert len(W) == 54, len(W)
start = datetime.date(2026, 11, 8)
random.seed(2026)
out = []
for i, w in enumerate(W):
    word, pron, pos, ok, b1, b2, ex, style, hook, comment, tag = w
    for o in (ok, b1, b2): assert len(o) <= 28, (word, o, len(o))
    assert len(ex) <= 70, (word, len(ex))
    assert word in ex.lower(), (word, ex)
    assert word in comment.lower(), (word, comment)
    ans = random.randrange(3)
    opts = [b1, b2]; opts.insert(ans, ok)
    L = "ABC"[ans]
    date = (start + datetime.timedelta(days=i)).isoformat()
    cap = f"{hook}\n\nGuess before the reveal 👀 A, B or C?\n\nFollow @canyouguessthisword for tomorrow's word\n\n#wordoftheday #vocabulary #englishwords #learnenglish #{tag}"
    out.append({
        "date": date, "hook_style": style, "hook": hook, "caption": cap, "first_comment": comment,
        "json": {"word": word, "pronunciation": pron, "part_of_speech": pos, "number": i + 4,
                 "options": opts, "answer": ans, "example": ex,
                 "captions": [[0.0, 3.3, "90% of people can't guess what this word means"],
                              [3.4, 6.9, f"{word.capitalize()}. Is it A, B, or C?"],
                              [7.0, 8.9, f"It's {L}! {ok}."],
                              [9.0, 12.5, ex],
                              [12.6, 14.6, "Use it in the comments!"]]}})
json.dump(out, open(sys.argv[1], "w"), indent=2, ensure_ascii=False)
from collections import Counter
print(len(out), Counter(o["hook_style"] for o in out), Counter(o["json"]["answer"] for o in out))
